rows = len(grid)
cols = len(grid[0])

# Check vertical symmetry (left-right mirror)
def has_vertical_symmetry():
    for r in range(rows):
        for c in range(cols // 2):
            if grid[r][c] != grid[r][cols - 1 - c]:
                return False
    return True

# Check horizontal symmetry (top-down mirror)
def has_horizontal_symmetry():
    for r in range(rows // 2):
        for c in range(cols):
            if grid[r][c] != grid[rows - 1 - r][c]:
                return False
    return True

# Check 180 degree rotational symmetry
def has_rotational_symmetry():
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != grid[rows - 1 - r][cols - 1 - c]:
                return False
    return True

print(f"Vertical symmetry: {has_vertical_symmetry()}")
print(f"Horizontal symmetry: {has_horizontal_symmetry()}")
print(f"Rotational symmetry: {has_rotational_symmetry()}")

